node -e "
const {Ajv} = require('./node_modules/ajv/dist/ajv.js');
const ajv = new Ajv({strictSchema: false, strictTypes: false, validateFormats: false});

function formatValidationErrors(errors) {
  return errors.map(e => (e.instancePath ? e.instancePath + ' ' : '') + (e.message ?? 'invalid')).join('; ').trim();
}

const validate = ajv.compile({
  type: 'object',
  properties: {ssn: {type: 'string'}},
  required: ['ssn'],
});

validate({ssn: 123456789});
const result = formatValidationErrors(validate.errors);
console.log('result:', JSON.stringify(result));
console.log('includesSSN:', result.includes('ssn'));
console.log('includesString:', result.includes('string'));
console.log('includesValue:', result.includes('123456789'));
"

